class EnvironmentUpdateArgs(_Args):
    """Arguments of `environment_update`."""
    skyTop: Any | None = Field(None, description='Sky color at the zenith — hex string "#rrggbb[aa]" or [r,g,b(,a)] in 0..1')
    skyHorizon: Any | None = Field(None, description='Sky color at the horizon — hex string "#rrggbb[aa]" or [r,g,b(,a)] in 0..1')
    ground: Any | None = Field(None, description='Ambient bounce color from below — hex string "#rrggbb[aa]" or [r,g,b(,a)] in 0..1')
    ambient: float | None = Field(None, description='Ambient light strength')
    sunAzimuth: float | None = Field(None, description='Sun compass direction in degrees (0 = +Z)')
    sunElevation: float | None = Field(None, description='Sun height above horizon in degrees')
    sunColor: Any | None = Field(None, description='Sun light color — hex string "#rrggbb[aa]" or [r,g,b(,a)] in 0..1')
    sunIntensity: float | None = Field(None, description='Sun brightness')
    fogColor: Any | None = Field(None, description='Distance fog color — hex string "#rrggbb[aa]" or [r,g,b(,a)] in 0..1')
    fogDensity: float | None = Field(None, description='Exponential fog density (0 = off)')
    exposure: float | None = Field(None, description='Camera exposure multiplier')
    autoExposure: bool | None = Field(None, description='Adapt exposure to scene brightness (eye adaptation)')
    exposureCompensation: float | None = Field(None, description='Exposure compensation in EV stops')
    adaptationSpeed: float | None = Field(None, description='Auto exposure adaptation speed')
    showGrid: bool | None = Field(None, description='Draw the editor ground grid')
    bloomIntensity: float | None = Field(None, description='Glow around bright/emissive things (0 = off)')
    bloomThreshold: float | None = Field(None, description='Brightness where glow starts (lower = more glow)')
    saturation: float | None = Field(None, description='Color saturation (1 = neutral)')
    contrast: float | None = Field(None, description='Contrast (1 = neutral)')
    vignette: float | None = Field(None, description='Darken the image corners')
    grain: float | None = Field(None, description='Film grain')
    chromaticAberration: float | None = Field(None, description='Lens color fringing toward the frame edges')
    look: Literal['none', 'warm', 'cool', 'teal_orange', 'golden_hour', 'bleach', 'noir', 'vivid', 'moonlight', 'vintage'] | None = Field(None, description='Color grading look')
    lut: str | None = Field(None, description='Optional .cube 3D LUT file (project-relative); when set it replaces the look (lookStrength blends it)')
    lookStrength: float | None = Field(None, description='Strength of the look / LUT')
    skyMode: Literal['gradient', 'atmosphere', 'hdri'] | None = Field(None, description='gradient = two artist colors; atmosphere = physically inspired sky from the sun; hdri = a photographed .hdr panorama lights and backs the scene (set `hdri`)')
    hdri: str | None = Field(None, description='Equirectangular .hdr panorama, project-relative (skyMode hdri)')
    hdriRotation: float | None = Field(None, description='Panorama rotation in degrees (line its sun up with sunAzimuth)')
    hdriIntensity: float | None = Field(None, description='Panorama brightness')
    clouds: float | None = Field(None, description='Procedural cloud cover')
    cloudMode: Literal['volumetric', 'flat'] | None = Field(None, description='Clouds: volumetric (ray-marched, lit, shadows) or flat (cheap)')
    cloudHeight: float | None = Field(None, description='Cloud layer base height in meters')
    cloudThickness: float | None = Field(None, description='Cloud layer thickness in meters')
    cloudDensity: float | None = Field(None, description='Cloud density: 0.3 wispy .. 2 stormy')
    cloudScale: float | None = Field(None, description='Cloud feature size (0.5 small puffs .. 3 huge banks)')
    cloudSpeed: float | None = Field(None, description='Cloud drift speed in m/s (along windDirection)')
    stars: float | None = Field(None, description='Stars in the night sky')
    sunSize: float | None = Field(None, description='Sun / moon disc size')
    fogHeight: float | None = Field(None, description='Fog pools near the ground as this grows (0 = uniform)')
    reflections: float | None = Field(None, description='Sky reflections / image-based lighting strength')
    ao: float | None = Field(None, description='Ambient occlusion (contact shadows in corners and creases)')
    aoRadius: float | None = Field(None, description='Ambient occlusion radius in meters')
    gi: float | None = Field(None, description='Screen-space global illumination: bounce and emissive light (0 = sky light only)')
    giDistance: float | None = Field(None, description='Global illumination ray length in meters')
    ssr: float | None = Field(None, description='Screen-space reflections on glossy surfaces (wet streets, floors, metal)')
    taa: bool | None = Field(None, description='Temporal anti-aliasing (smooth edges, stable shimmer-free detail)')
    renderScale: float | None = Field(None, description='Real-time internal resolution: 0.5-0.77 renders fewer pixels and MetalFX temporal upscaling reconstructs full resolution (faster); 1 = native. Stills and captures with samples > 1 render native.')
    sharpen: float | None = Field(None, description='Sharpening after temporal anti-aliasing')
    shadowSoftness: float | None = Field(None, description='Sun shadow penumbra size')
    tonemap: Literal['aces', 'agx', 'neutral', 'filmic', 'none'] | None = Field(None, description='HDR to display curve')
    temperature: float | None = Field(None, description='White balance: -1 cool .. +1 warm')
    tint: float | None = Field(None, description='White balance: -1 green .. +1 magenta')
    shadowDistance: float | None = Field(None, description='Sun shadow range in meters (0 = automatic)')
    godRays: float | None = Field(None, description='Volumetric light: sun shafts through trees and windows, cones under lamps (0 = off, 1 = natural)')
    haze: float | None = Field(None, description='Air density for volumetric light, extinction per meter: 0.0003 clear landscape, 0.002 hazy valley, 0.01-0.03 misty alley or interior')
    windSpeed: float | None = Field(None, description='Wind (m/s) that carries smoke, rain, snow and particles')
    windDirection: float | None = Field(None, description='Direction the wind blows toward (degrees, 0 = +Z)')
    localShadowAtlas: int | None = Field(None, description='Point/spot shadow atlas size in px: 2048 (16 MB), 4096 (64 MB, default), 8192 (256 MB)')
    localShadowLights: int | None = Field(None, description='Most point/spot lights with shadows per frame (the most important on screen); the rest light without shadows. 0 = no local shadows')
    localShadowUpdates: int | None = Field(None, description='Point/spot shadow views re-rendered per frame when lights or casters move (cube light = 6, spot = 1); later updates wait a frame. Stills render all')
    probeBudget: int | None = Field(None, description='Reflection probes with a slot in the probe atlas (the most important in view first; the rest fall back to the sky). Max 32; 0 = probes off')
    probeUpdates: int | None = Field(None, description='Reflection probe cube faces captured per frame (a whole probe = 6); later captures wait a frame. Stills capture everything')
    preset: Literal['noon', 'sunset', 'night', 'overcast', 'studio'] | None = Field(None, description='Lighting preset')
    align_sun_to_hdri: bool | None = Field(None, description='Point the sun (direction of light and shadows) at the brightest spot of the hdri panorama')


