    clay: bool | None = Field(None, description="Render every surface as matte white clay (judge form and light; film 'sketch to fill' beats)")
    debug_view: Literal['final', 'albedo', 'normals', 'material', 'gi', 'reflections', 'ao', 'depth', 'lighting', 'sketch', 'impostors', 'wireframe', 'overdraw', 'unshaded', 'lighting_only', 'shadow_cascades', 'light_complexity', 'lod', 'emission', 'specular', 'uv_checker', 'texel_density', 'motion', 'shadow_atlas', 'reflection_probes'] | None = Field(None, description='Diagnostic view instead of the final image. Buffers: albedo, normals, material (roughness red / metallic green), gi, reflections, ao, depth, lighting. Shading: unshaded, lighting_only (white material), emission, specular. Geometry: wireframe, overdraw (heat map), lod (green 0 .. red 3), uv_checker, texel_density (green = 512 texels/m). Lights: shadow_cascades (red/green/blue/yellow), light_complexity (lights per pixel heat map), shadow_atlas (point/spot shadow maps, outlined per light: green re-rendered, blue cached, orange waiting; see shadow_atlas_info), reflection_probes (which probe lights each pixel, their volumes; see probe_info). Motion: the velocity buffer (hue = direction, strength = speed). Also sketch, impostors. Full legend: viewport_debug_view {"list": true}')
    quality: Literal['full', 'balanced', 'fast'] | None = Field(None, description='Viewport quality tier (default full; fast/balanced preview what the editor shows while editing)')
    include_image: bool | None = Field(None, description='Return the image (default true); false = only the entity list')
    save_path: str | None = Field(None, description='Also write the PNG to this project-relative path')
    alpha: float | None = Field(None, description='While playing: render the in-between frame a real-time display shows this far between the last two ticks (0..1; render interpolation). Default 1 = the exact tick state')
    frame_handlers: bool | None = Field(None, description='While playing: also run the cosmetic `on frame` Wander handlers for this image (camera shake, UI tweens); their writes are undone afterwards')
    probe: int | str | None = Field(None, description="Return this reflection probe's captured cubemap instead (6 faces as a horizontal cross: +Y on top; -X, +Z, +X, -Z across; -Y below)")
    probe_mip: int | None = Field(None, description='With probe: roughness level 0 (sharp) .. 5 (the diffuse ambient)')


