    async def entity_delete(self, *, entity: int | str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Delete an entity and all its children (undoable)."""
        return await self._c.call('entity_delete', _args(EntityDeleteArgs, {'entity': entity}), check=check, timeout=timeout)

    async def entity_duplicate(self, *, entity: int | str | None = None, entities: list[int | str] | None = None, name: str | None = None, offset: list[float] | None = None, count: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Copy an entity (with children, components and behaviors). Optional new name and position offset. `entities` duplicates several together: links between them (joint targets, look-at, follow...) point at the copies, so a duplicated rig stays wired to itself. Prefab instances stay linked."""
