    async def history(self, *, action: Literal['undo', 'redo', 'list'], steps: int | None = None, limit: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Undo or redo edits (by anyone), or list recent history entries with who made them."""
