    async def material_update(self, *, path: str, color: Any | None = None, metallic: float | None = None, roughness: float | None = None, emissive: Any | None = None, texture: str | None = None, tilingU: float | None = None, tilingV: float | None = None, unlit: bool | None = None, shading: Literal['pbr', 'toon', 'unlit', 'water'] | None = None, normalMap: str | None = None, ormMap: str | None = None, emissiveMap: str | None = None, normalStrength: float | None = None, triplanar: bool | None = None, clearcoat: float | None = None, subsurface: float | None = None, rim: float | None = None, outline: float | None = None, outlineColor: Any | None = None, doubleSided: bool | None = None, occlusionStrength: float | None = None, alphaCutoff: float | None = None, preset: Literal['gold', 'silver', 'copper', 'chrome', 'brushed_steel', 'iron', 'plastic', 'rubber', 'ceramic', 'car_paint', 'glass', 'water', 'ice', 'skin', 'wax', 'leaves', 'snow', 'velvet', 'neon', 'toon', 'toon_metal', 'clay'] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Change fields of an existing material; every entity using it updates instantly."""
        return await self._c.call('material_update', _args(MaterialUpdateArgs, {'color': color, 'metallic': metallic, 'roughness': roughness, 'emissive': emissive, 'texture': texture, 'tilingU': tilingU, 'tilingV': tilingV, 'unlit': unlit, 'shading': shading, 'normalMap': normalMap, 'ormMap': ormMap, 'emissiveMap': emissiveMap, 'normalStrength': normalStrength, 'triplanar': triplanar, 'clearcoat': clearcoat, 'subsurface': subsurface, 'rim': rim, 'outline': outline, 'outlineColor': outlineColor, 'doubleSided': doubleSided, 'occlusionStrength': occlusionStrength, 'alphaCutoff': alphaCutoff, 'path': path, 'preset': preset}), check=check, timeout=timeout)

    async def movie_render(self, *, action: Literal['render', 'status', 'cancel'] | None = None, sequence: Any | None = None, camera: Any | None = None, camera_entity: int | str | None = None, simulate: bool | None = None, start: float | None = None, end: float | None = None, duration: float | None = None, fps: int | None = None, resolution: Literal['720p', '1080p', '1440p', '4k'] | None = None, width: int | None = None, height: int | None = None, samples: int | None = None, shutter: float | None = None, shutter_samples: int | None = None, shutter_timing: Literal['center', 'open', 'close'] | None = None, quality: Literal['full', 'balanced', 'fast'] | None = None, clay: bool | None = None, debug_view: Literal['final', 'albedo', 'normals', 'material', 'gi', 'reflections', 'ao', 'depth', 'lighting', 'sketch', 'impostors', 'wireframe', 'overdraw', 'unshaded', 'lighting_only', 'shadow_cascades', 'light_complexity', 'lod', 'emission', 'specular', 'uv_checker', 'texel_density', 'motion', 'shadow_atlas', 'reflection_probes'] | None = None, warmup: int | None = None, output: str | None = None, outputs: list[Any] | None = None, codec: Literal['png', 'h264', 'hevc', 'prores', 'prores4444'] | None = None, bitrate_mbps: float | None = None, resume: bool | None = None, name: str | None = None, background: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Render a cinematic to video or a PNG sequence, offline and deterministically (the movie renderer). Renders a sequence (`sequence`: its entity or .sequence.json, whole length or start/end), an inline camera move (`camera`: {keys: [{t, eye, target, fov?, roll?}]} splined, or {shots: [{shot: orbit|dolly|crane|track|pan|static|path|flyover, duration, target, ...sequence_camera_shot fields}]} where each shot is a cut), or the scene camera for `duration` seconds. Always starts from the scene state and restores it after. simulate=true runs the game (scripts, physics); false (default) runs only sequences, animators and particles. Motion blur: `shutter` 0..1 of the frame (0.5 = 180 degrees; default the camera's motionBlur) accumulates sub-frames at fractional times; `samples` (default 8) is the per-frame budget. Outputs by extension: .mp4 = H.264 (codec hevc = 10-bit HEVC), .mov = ProRes 422 HQ, a folder or name_####.png = PNG sequence (resume=true continues an interrupted one). clay=true / debug_view="sketch" render the same move as clay or pencil sketch. Blocks until done and returns frames, timings and paths; background=true returns at once (progress: movie_progress events, action="status"; action="cancel" stops). Example: {"sequence": "Intro", "output": "renders/intro.mp4", "resolution": "1080p", "fps": 24, "shutter": 0.5, "samples": 16}."""
        return await self._c.call('movie_render', _args(MovieRenderArgs, {'action': action, 'sequence': sequence, 'camera': camera, 'camera_entity': camera_entity, 'simulate': simulate, 'start': start, 'end': end, 'duration': duration, 'fps': fps, 'resolution': resolution, 'width': width, 'height': height, 'samples': samples, 'shutter': shutter, 'shutter_samples': shutter_samples, 'shutter_timing': shutter_timing, 'quality': quality, 'clay': clay, 'debug_view': debug_view, 'warmup': warmup, 'output': output, 'outputs': outputs, 'codec': codec, 'bitrate_mbps': bitrate_mbps, 'resume': resume, 'name': name, 'background': background}), check=check, timeout=timeout)

    async def native_build(self, *, force: bool | None = None, load: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Compile the project's native C++ module (native/*.cpp against skywalker/native/sdk.h, plus flags, include dirs, libraries, frameworks and pkg-config packages from native/module.json) into a library with the system clang++, then load it: its builtins become callable from every behavior (they appear in wander_reference) and its systems run every tick while playing. Compiler errors come back as structured diagnostics {file, line, column, message} relative to the project. Unchanged sources load the cached build instantly. Security: this runs native code you or an agent wrote inside the engine; review it first."""
        return await self._c.call('native_build', _args(NativeBuildArgs, {'force': force, 'load': load}), check=check, timeout=timeout)

    async def native_list(self, *, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Status of the project's native code: whether native sources exist, the C++ compiler, the last build and its diagnostics, the loaded module with its builtins (signatures) and systems, and behaviors running as AOT-compiled native code."""
        return await self._c.call('native_list', _args(NativeListArgs, {}), check=check, timeout=timeout)

    async def native_template(self, *, name: str | None = None, overwrite: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Write a starter native module: native/<name>.cpp (a builtin `wave(t, freq)` and a per-tick system that spins entities tagged "spinner") and native/module.json (flags, include_dirs, lib_dirs, libs, frameworks, pkg_config). Edit it, then native_build. Use it for hot inner loops (flocking, procedural generation, custom physics) or to bring in any C++ library (e.g. Homebrew packages via pkg_config)."""
        return await self._c.call('native_template', _args(NativeTemplateArgs, {'name': name, 'overwrite': overwrite}), check=check, timeout=timeout)

    async def nav_build(self, *, agent_radius: float | None = None, agent_height: float | None = None, max_climb: float | None = None, max_slope: float | None = None, cell_size: float | None = None, cell_height: float | None = None, tile_size: int | None = None, geometry: Literal['both', 'colliders', 'meshes'] | None = None, save: bool | None = None, path: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Bake (or rebuild) the navigation mesh from static colliders and static meshes, save it to the project and record the settings in the scene's `navmesh` component (one undoable edit; creates an entity named "Navigation" if needed). Re-run after changing the level layout. Settings default to the navmesh component's: agent_radius (walls eroded by it), agent_height, max_climb (steps), max_slope (degrees), cell_size (precision). Entities tagged "nav_ignore" are left out. Then use nav_path / nav_debug, or nav agents and navigate() in Wander."""
        return await self._c.call('nav_build', _args(NavBuildArgs, {'agent_radius': agent_radius, 'agent_height': agent_height, 'max_climb': max_climb, 'max_slope': max_slope, 'cell_size': cell_size, 'cell_height': cell_height, 'tile_size': tile_size, 'geometry': geometry, 'save': save, 'path': path}), check=check, timeout=timeout)

    async def nav_debug(self, *, focus: int | str | None = None, from_: Any | None = None, to: Any | None = None, size: int | None = None, include_image: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Top-down map of the level with the navmesh drawn over it (teal = walkable), nav agents (yellow dots) with their current paths, and optionally a test path between two points (orange). The fastest way to spot unreachable rooms, doorways too narrow for agents, and gaps. Bakes the navmesh first if needed."""
        return await self._c.call('nav_debug', _args(NavDebugArgs, {'focus': focus, 'from': from_, 'to': to, 'size': size, 'include_image': include_image}), check=check, timeout=timeout)

    async def nav_path(self, *, from_: Any, to: Any, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Walking path on the navmesh between two points or entities (bakes the navmesh first if needed). Returns the corner points, the walking length, and whether the goal is reachable (partial = it is not; the path ends at the closest reachable point). Use to check that a level is traversable or to plan patrols. Example: {"from": "Player", "to": [12, 0, -4]}."""
        return await self._c.call('nav_path', _args(NavPathArgs, {'from': from_, 'to': to}), check=check, timeout=timeout)

    async def perf_stats(self, *, frames: int | None = None, width: int | None = None, height: int | None = None, view: Any | None = None, quality: Literal['full', 'balanced', 'fast'] | None = None, passes: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Frame cost and scene complexity: GPU and CPU frame time, draw calls, lights, terrain nodes, foliage instances, entities, behaviors and assets. Pass frames (e.g. 30) to benchmark real-time rendering of the current view at width x height (temporal AA, no supersampling) and get average/min/max GPU ms. Check after big scatters, generators or look changes; 16.6 ms = 60 fps. view is "editor", "scene" or a custom camera {eye, target, fov}; quality benchmarks an editor viewport tier. The gpu section includes foliage impostor stats (impostorInstances, meshInstances, impostorsBaked, impostorBakeMs). passes=true adds where the frame time goes: profile.passes = GPU time per render pass (Main, Shadow cascades, SSGI, SSR, Lighting resolve, TAA, Bloom, Composite, Foliage cull, GPU particles, Hair ...; rolling 60-frame avg/min/max), profile.groups = the same summed by area (shadows, main, ao, ssgi, ssr, resolve, effects, volumetrics, clouds, temporal, post, foliage, particles, hair, ui ...) and profile.cpu = CPU scopes (frame.build, scene.buildFrame, world.gather, render.encode ...). With frames > 0 the profile covers exactly the benchmark frames. Example: {"frames":30,"passes":true,"view":{"eye":[0,300,-600],"target":[0,80,0]}}."""
        return await self._c.call('perf_stats', _args(PerfStatsArgs, {'frames': frames, 'width': width, 'height': height, 'view': view, 'quality': quality, 'passes': passes}), check=check, timeout=timeout)

    async def physics_add(self, *, preset: Literal['prop', 'static_level', 'kinematic_platform', 'player_character', 'npc_character', 'trigger_zone', 'debris', 'projectile', 'remove'], entity: int | str | None = None, entities: list[int | str] | None = None, overrides: dict[str, Any] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Make entities physical with a preset (one undoable edit). prop = dynamic rigid body with a collider fitted to its mesh and a mass estimated from its size; static_level = static colliders for every mesh under the entity (triangle-exact for imported models) — use on level roots; kinematic_platform = moved by its transform/scripts, carries and pushes things; player_character / npc_character = capsule character controller fitted to the mesh (drive with walk/jump in Wander); trigger_zone = sensor that fires `on trigger_enter`/`on trigger_exit`; debris = light, does not collide with characters; projectile = fast (continuous collision); remove = strip body/collider/character/joint. `overrides` patches the components, e.g. {"body": {"mass": 80, "restitution": 0.6}, "collider": {"shape": "sphere"}}. Example: {"entities": ["Crate 1", "Crate 2"], "preset": "prop"}."""
        return await self._c.call('physics_add', _args(PhysicsAddArgs, {'entity': entity, 'entities': entities, 'preset': preset, 'overrides': overrides}), check=check, timeout=timeout)

    async def physics_debug(self, *, view: Literal['editor', 'scene', 'top'] | None = None, focus: int | str | None = None, width: int | None = None, height: int | None = None, show_static: bool | None = None, include_image: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Capture the viewport with every collider drawn as a wireframe (color = state) plus physics stats (bodies, awake/asleep, contacts, triggers, characters, joints) and warnings (bad layers, unsupported shapes, missing joint targets). Use it to check that colliders match the visuals, triggers sit where you expect, and props fall asleep. view: editor (default), scene camera, or top (orthographic map)."""
        return await self._c.call('physics_debug', _args(PhysicsDebugArgs, {'view': view, 'focus': focus, 'width': width, 'height': height, 'show_static': show_static, 'include_image': include_image}), check=check, timeout=timeout)

    async def physics_query(self, *, type: Literal['raycast', 'raycast_all', 'shapecast', 'overlap'], origin: list[float], direction: list[float] | None = None, max_distance: float | None = None, shape: Literal['sphere', 'box', 'capsule'] | None = None, radius: float | None = None, height: float | None = None, half_extents: list[float] | None = None, rotation: list[float] | None = None, exclude: list[int | str] | None = None, include_triggers: bool | None = None, layers: list[str] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Ask the collision world (colliders, not render meshes) — works while editing and playing. raycast = first hit along a ray; raycast_all = every entity along it; shapecast = sweep a sphere/box/capsule (will this fit / where does it land?); overlap = entities touching a shape at `origin` (is this spot free?). Triggers are ignored unless include_triggers. Example: {"type": "raycast", "origin": [0, 10, 0], "direction": [0, -1, 0]}."""
        return await self._c.call('physics_query', _args(PhysicsQueryArgs, {'type': type, 'origin': origin, 'direction': direction, 'max_distance': max_distance, 'shape': shape, 'radius': radius, 'height': height, 'half_extents': half_extents, 'rotation': rotation, 'exclude': exclude, 'include_triggers': include_triggers, 'layers': layers}), check=check, timeout=timeout)

    async def physics_settings(self, *, gravity: list[float] | None = None, substeps: int | None = None, ignorePairs: str | None = None, allowSleep: bool | None = None, enabled: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Read or change scene-wide physics: gravity (m/s^2), substeps (stability for stacks/fast objects), which collision layers ignore each other (ignorePairs, e.g. "debris-player, projectile-projectile"), sleeping, on/off. Stored in a `physics_world` component (created on an entity named "Physics" when you first change it). Example: {"gravity": [0, -1.62, 0]} for the Moon."""
        return await self._c.call('physics_settings', _args(PhysicsSettingsArgs, {'gravity': gravity, 'substeps': substeps, 'ignorePairs': ignorePairs, 'allowSleep': allowSleep, 'enabled': enabled}), check=check, timeout=timeout)

    async def physics_settle(self, *, entity: int | str | None = None, entities: list[int | str] | None = None, seconds: float | None = None, freeze_others: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Drop objects with a real simulation and keep where they come to rest (simulate, then keep the poses). Only the listed entities move (as dynamic bodies, even without a body component); everything else is frozen. The result is ONE undoable edit. Great after scatter/place: rocks, crates, books and debris end up naturally stacked and resting instead of floating or intersecting. Example: {"entities": ["Crate 1", "Crate 2", "Barrel"], "seconds": 4}."""
        return await self._c.call('physics_settle', _args(PhysicsSettleArgs, {'entity': entity, 'entities': entities, 'seconds': seconds, 'freeze_others': freeze_others}), check=check, timeout=timeout)

    async def place_on_surface(self, *, entities: list[int | str], offset: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Move entities straight down (or up) so the bottom of their bounds rests on the geometry below them. Great after placing props roughly on uneven terrain. One undo step."""
        return await self._c.call('place_on_surface', _args(PlaceOnSurfaceArgs, {'entities': entities, 'offset': offset}), check=check, timeout=timeout)

    async def playtest_compare(self, *, before: str, after: str, feedback: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Before/after comparison of two playtests (ids like P-3): every metric with its delta and whether it got better or worse (direction-aware: fewer deaths is better, higher completion is better). Pass feedback to record the result as that feedback's measured effect: improved → verified, regressed → regressed (its tasks reopen). Timing metrics (*_ms, est_fps) depend on the machine's load, so they only decide the verdict for performance feedback or when a target names them; they are always listed."""
        return await self._c.call('playtest_compare', _args(PlaytestCompareArgs, {'before': before, 'after': after, 'feedback': feedback, 'as': as_}), check=check, timeout=timeout)

    async def playtest_run(self, *, policy: Literal['goal_seeker', 'explorer', 'random', 'scripted'] | None = None, seconds: float | None = None, runs: int | None = None, seed: int | None = None, persona: dict[str, Any] | None = None, controls: dict[str, Any] | None = None, script: list[dict[str, Any]] | None = None, player: int | str | None = None, goal_radius: float | None = None, screenshots: bool | None = None, screenshot_interval: float | None = None, max_screenshots: int | None = None, label: str | None = None, agent: str | None = None, include_heatmap: bool | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Play the game with a bot in a sandbox copy of the scene (the scene you edit is untouched) and get a report: completion rate, time-to-goal, deaths and their causes, fails, damage, stuck periods, objectives, coverage, frame cost, screenshots at notable moments and a top-down heatmap (returned as an image). Policies: goal_seeker (walks to entities tagged "goal"/"objective", avoids "hazard"/"enemy"), explorer (covers unexplored space), random, scripted (script: [{t: seconds, hold|release|press|click|event: ...}] — the same arguments as sim_input). persona {reaction_time, skill, curiosity, patience} shapes the bot; playtester agents use their own persona by default. runs>1 aggregates several seeds. Games should tag the player "player" and emit "death" / "fail" / "damage" / "objective" events. Saved under studio/playtests/<id>/; findings are returned for filing as feedback."""
        return await self._c.call('playtest_run', _args(PlaytestRunArgs, {'policy': policy, 'seconds': seconds, 'runs': runs, 'seed': seed, 'persona': persona, 'controls': controls, 'script': script, 'player': player, 'goal_radius': goal_radius, 'screenshots': screenshots, 'screenshot_interval': screenshot_interval, 'max_screenshots': max_screenshots, 'label': label, 'agent': agent, 'include_heatmap': include_heatmap, 'as': as_}), check=check, timeout=timeout)

    async def prefab_apply(self, *, entity: int | str, property: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Push an instance's overrides into its prefab file so every instance (in all scenes) gets them. Without `property`: everything — overrides, removed nodes and added entities (they become prefab nodes and stay linked). With `property`: only that override of `entity`. Placement (root name/transform) is never applied. Other instances in this scene update immediately and keep their own overrides. Undo restores the scene; the file keeps the new version (re-apply or edit to change it back)."""
        return await self._c.call('prefab_apply', _args(PrefabApplyArgs, {'entity': entity, 'property': property}), check=check, timeout=timeout)

    async def prefab_create(self, *, entity: int | str, path: str, description: str | None = None, tags: list[str] | None = None, link: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Save an entity and all its children (components, behaviors, vars, tags) as a reusable prefab asset. Instantiate it with prefab_instantiate, scatter, or Wander spawn("prefab:path"). By default the entity itself becomes a linked instance of the new prefab (link=false leaves it unlinked)."""
        return await self._c.call('prefab_create', _args(PrefabCreateArgs, {'entity': entity, 'path': path, 'description': description, 'tags': tags, 'link': link}), check=check, timeout=timeout)

    async def prefab_instantiate(self, *, prefab: str, position: list[float] | None = None, yaw: float | None = None, rotation: list[float] | None = None, scale: float | None = None, parent: int | str | None = None, name: str | None = None, on_surface: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Create a linked instance of a prefab: the scene stores only what you change on it (prefab_overrides), and editing the prefab updates every instance. Optionally drop it onto the surface below its position."""
        return await self._c.call('prefab_instantiate', _args(PrefabInstantiateArgs, {'prefab': prefab, 'position': position, 'yaw': yaw, 'rotation': rotation, 'scale': scale, 'parent': parent, 'name': name, 'on_surface': on_surface}), check=check, timeout=timeout)

    async def prefab_overrides(self, *, entity: int | str | None = None, prefab: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """How a linked prefab instance differs from its prefab: per-field overrides (with the prefab's value), removed nodes, added entities and its placement (root name/transform, never applied). `entity` may be the instance root or any entity inside it. Without `entity`: every instance in the scene with its override count. Then use prefab_revert to undo overrides or prefab_apply to push them into the prefab file."""
        return await self._c.call('prefab_overrides', _args(PrefabOverridesArgs, {'entity': entity, 'prefab': prefab}), check=check, timeout=timeout)

    async def prefab_relink(self, *, prefab: str, entities: list[int | str] | None = None, max_overrides: int | None = None, dry_run: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Link existing copies of a prefab (made before prefabs were linked, or by copying entities) back to it. A candidate links when its hierarchy matches the prefab node for node (same child names in order) and it has at most `max_overrides` differences besides placement; values are never changed (differences become overrides). Without `entities` the whole scene is searched. dry_run reports without linking."""
        return await self._c.call('prefab_relink', _args(PrefabRelinkArgs, {'prefab': prefab, 'entities': entities, 'max_overrides': max_overrides, 'dry_run': dry_run}), check=check, timeout=timeout)

    async def prefab_revert(self, *, entity: int | str, property: str | None = None, all: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Undo overrides so an instance matches its prefab again. `property` reverts one override of `entity` ("light.intensity", "name", "vars.hp", "collider" for an added/removed component); without it, all of that entity's overrides (placement kept). `all`: true reverts the whole instance and restores removed nodes (added entities stay). Undoable."""
        return await self._c.call('prefab_revert', _args(PrefabRevertArgs, {'entity': entity, 'property': property, 'all': all}), check=check, timeout=timeout)

    async def prefab_unpack(self, *, entity: int | str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Make an instance local: its entities stay exactly as they are but are no longer linked to the prefab (edits to the prefab stop reaching it, and the scene saves it in full); also known as "make local". Undoable."""
        return await self._c.call('prefab_unpack', _args(PrefabUnpackArgs, {'entity': entity}), check=check, timeout=timeout)

    async def probe_add(self, *, position: list[float], name: str | None = None, parent: int | str | None = None, size: Any | None = None, shape: Literal['box', 'sphere'] | None = None, radius: float | None = None, interior: bool | None = None, update: Literal['once', 'on_change', 'realtime'] | None = None, interval: int | None = None, resolution: int | None = None, priority: int | None = None, blend_distance: float | None = None, box_projection: bool | None = None, intensity: float | None = None, ambient: Literal['probe', 'sky', 'color'] | None = None, ambient_color: str | None = None, cull_mask: Any | None = None, render: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Add a reflection probe: a captured cubemap that glossy floors, metal and glass inside its volume reflect instead of the sky (box-projected, so reflections line up with the walls), and that gives them their ambient light. Put one per room, corridor or street section, with the capture point in open space at about eye height. size "auto" (default) casts rays from `position` to the nearest meshes in the six axis directions and fits the box to the room (open directions get 8 m): the volume reaches blend_distance past the walls and the reflections project onto the room (projectionSize); or give [x, y, z] in meters. interior=true for closed rooms: no sky light leaks in (the probe replaces it; windows still show the sky). update: once (default, cached until it moves or probe_bake), on_change (re-captures when something in range changes), realtime (every `interval` frames, within Environment.probeUpdates faces per frame). The new probe is captured right away and its state returned (see probe_info). Example: {"name": "Hall Probe", "position": [0, 1.6, 0], "interior": true}."""
        return await self._c.call('probe_add', _args(ProbeAddArgs, {'name': name, 'position': position, 'parent': parent, 'size': size, 'shape': shape, 'radius': radius, 'interior': interior, 'update': update, 'interval': interval, 'resolution': resolution, 'priority': priority, 'blend_distance': blend_distance, 'box_projection': box_projection, 'intensity': intensity, 'ambient': ambient, 'ambient_color': ambient_color, 'cull_mask': cull_mask, 'render': render}), check=check, timeout=timeout)

    async def probe_bake(self, *, probes: Any | None = None, view: Any | None = None, render: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Re-capture reflection probes now (after moving furniture, changing lights or the sky): renders one still frame of `view`, which captures every invalidated probe in full regardless of the per-frame face budget, and returns their state (slot, captures, GPU time) plus warnings. probes: one entity, a list or "all" (default). render=false only marks them; they re-capture over the next frames (Wander: probe_bake()). Example: {"probes": ["Hall Probe"]}."""
        return await self._c.call('probe_bake', _args(ProbeBakeArgs, {'probes': probes, 'view': view, 'render': render}), check=check, timeout=timeout)

    async def probe_info(self, *, view: Any | None = None, entity: int | str | None = None, render: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Reflection probes and their atlas: the budget (Environment.probeBudget probes, probeUpdates faces per frame), atlas resolution / slots / memory, and per probe: slot and debug color (the reflection_probes debug view draws it), whether it is captured, lighting this view, waiting for the face budget, over budget or out of view, captures so far, last capture GPU time, `stale` (something in range changed since a once probe was captured: run probe_bake), size, update mode. Warnings: overlapping volumes with equal priority, probes with no geometry in them, capture points inside a mesh, atlas exhaustion. Renders one real-time frame of `view` first. See the volumes with viewport_capture {debug_view: "reflection_probes"} and a probe's cubemap with viewport_capture {probe: "Hall Probe"}. Example: {"entity": "Hall Probe"}."""
        return await self._c.call('probe_info', _args(ProbeInfoArgs, {'view': view, 'entity': entity, 'render': render}), check=check, timeout=timeout)

    async def process_info(self, *, entity: int | str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """What runs while the game is paused or slowed, and how smooth real-time frames are. Reports the game clock (paused?, time scale, game vs real time), every entity with a `process` component or a UI canvas (UI runs `always` by default), and with `entity` that entity's effective settings and WHY (which ancestor decided its mode). Also render interpolation: alpha, entities smoothed last frame, `on frame` handler runs and frame pacing jitter (jitterMs vs jitterMsWithoutInterpolation). Warnings flag a paused game nothing can resume. Example: {"entity": "PauseMenu"}."""
        return await self._c.call('process_info', _args(ProcessInfoArgs, {'entity': entity}), check=check, timeout=timeout)

    async def raycast(self, *, origin: list[float] | None = None, direction: list[float] | None = None, x: float | None = None, y: float | None = None, width: int | None = None, height: int | None = None, exclude: list[int | str] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Cast a ray into the scene and get the first mesh hit (triangle-accurate): entity, point, surface normal and distance. Give origin+direction in world space, or a pixel x,y of an editor-camera capture (width/height). Use it to find the ground height, check line of sight, or aim placements."""
        return await self._c.call('raycast', _args(RaycastArgs, {'origin': origin, 'direction': direction, 'x': x, 'y': y, 'width': width, 'height': height, 'exclude': exclude}), check=check, timeout=timeout)

    async def render_layers(self, *, action: Literal['get', 'name', 'set'] | None = None, layer: int | None = None, name: str | None = None, entities: list[int | str] | None = None, layers: Any | None = None, cull_mask: Any | None = None, mode: Literal['replace', 'add', 'remove'] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Render layers (20): MeshRenderer.layers says which layers a mesh is on; Camera.cullMask and Light.cullMask say which layers a camera draws and a light illuminates (a mesh is drawn / lit when they share a layer). Name layers in game.json and use the names everywhere. action get (default): named layers, meshes per layer, cameras and lights with restricted masks, plus warnings (meshes no camera sees, lights that light nothing). action name: {layer: 2, name: "player"} (name "" clears). action set: {entities, layers} puts meshes on layers and/or {entities, cull_mask} sets cameras' and lights' masks; masks accept a number (raw bits), a layer name, "3", "all", "none" or a list; mode add/remove edits the existing mask instead of replacing it. Uses: a rim light only on the hero ({entities:["RimLight"], cull_mask:"hero"}), first-person arms hidden from a mirror camera, editor-only helpers on layer 20 hidden from the game camera. Example: {"action":"set","entities":["Hero"],"layers":["world","hero"]}"""
        return await self._c.call('render_layers', _args(RenderLayersArgs, {'action': action, 'layer': layer, 'name': name, 'entities': entities, 'layers': layers, 'cull_mask': cull_mask, 'mode': mode}), check=check, timeout=timeout)

    async def scatter(self, *, count: int, source: int | str | None = None, prefab: str | None = None, center: list[float] | None = None, size: list[float] | None = None, radius: float | None = None, min_distance: float | None = None, yaw: Any | None = None, scale: Any | None = None, on_surface: bool | None = None, surface: int | str | None = None, seed: int | None = None, group: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Procedurally place many copies of an entity or prefab in an area — forests, rocks, coins, crowds. Deterministic for a given seed. Random yaw/scale ranges, minimum spacing, and optional snapping to the surface below. All copies go under a new group entity; the whole operation is one undo step."""
        return await self._c.call('scatter', _args(ScatterArgs, {'source': source, 'prefab': prefab, 'count': count, 'center': center, 'size': size, 'radius': radius, 'min_distance': min_distance, 'yaw': yaw, 'scale': scale, 'on_surface': on_surface, 'surface': surface, 'seed': seed, 'group': group}), check=check, timeout=timeout)

    async def scene_audit(self, *, camera: dict[str, Any] | None = None, cameras: list[dict[str, Any]] | None = None, camera_entity: int | str | None = None, view: Literal['editor', 'scene'] | None = None, sequence: Any | None = None, times: list[float] | None = None, strict: bool | None = None, max_primitive_coverage: float | None = None, stylized: bool | None = None, width: int | None = None, height: int | None = None, resolution: int | None = None, details: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Quality gate before filming or screenshots (read-only, CPU, no GPU needed). Builds the frame a camera sees and reports: visible builtin PRIMITIVE meshes (cube, sphere, capsule, cylinder, plane, cone, quad, torus) with entity and screen coverage % (occlusion-aware: a ground plane hidden under terrain or water does not count); PRIMITIVE CHARACTERS (an animator / character controller / nav agent on primitive meshes, or primitive parts arranged like a body, e.g. a sphere head on a capsule) with a kit character to replace them; DEFAULT grey or UNTEXTURED materials on visible meshes; missing texture / material / HDRI files; big meshes without LODs; texel-density outliers; a default sky; lights without shadows on hero meshes. Returns `pass` and `warnings` [{severity, code, message, hint, entity}]. Views: `camera` {eye, target, fov}, several `cameras`, `camera_entity`, `view` (editor | scene), or a `sequence` (path or sequencer entity) at `times` (seconds; default: 12 evenly spaced shots). strict=true fails when primitives (or default materials) cover more than 0.1% of any view (default limit 2%); override with max_primitive_coverage (percent). stylized=true accepts flat-colored materials (a deliberate stylized look). Examples: {"view": "scene", "strict": true}, {"sequence": "sequences/hero.sequence.json", "times": [1, 4, 8], "strict": true}, {"camera": {"eye": [0, 1.7, 5], "target": [0, 1.2, 0], "fov": 40}}."""
        return await self._c.call('scene_audit', _args(SceneAuditArgs, {'camera': camera, 'cameras': cameras, 'camera_entity': camera_entity, 'view': view, 'sequence': sequence, 'times': times, 'strict': strict, 'max_primitive_coverage': max_primitive_coverage, 'stylized': stylized, 'width': width, 'height': height, 'resolution': resolution, 'details': details}), check=check, timeout=timeout)

    async def scene_load(self, *, path: str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Load a scene file (replaces the current scene and clears history)."""
        return await self._c.call('scene_load', _args(SceneLoadArgs, {'path': path}), check=check, timeout=timeout)

    async def scene_new(self, *, name: str | None = None, empty: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Start a new scene. By default it contains a ground plane, a cube and a camera; empty=true for nothing."""
        return await self._c.call('scene_new', _args(SceneNewArgs, {'name': name, 'empty': empty}), check=check, timeout=timeout)

    async def scene_overview(self, *, max_entities: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Compact outline of the whole scene: every entity as one line (id, name, mesh/color, position, tags) in hierarchy order, plus environment, selection and the scene file (`path`; empty until saved). Start here before editing."""
        return await self._c.call('scene_overview', _args(SceneOverviewArgs, {'max_entities': max_entities}), check=check, timeout=timeout)

    async def scene_query(self, *, name: str | None = None, tag: str | None = None, component: str | None = None, near: list[float] | None = None, radius: float | None = None, limit: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Find entities by name glob (e.g. "tree*"), tag, component, or proximity. Returns one line per match."""
        return await self._c.call('scene_query', _args(SceneQueryArgs, {'name': name, 'tag': tag, 'component': component, 'near': near, 'radius': radius, 'limit': limit}), check=check, timeout=timeout)

    async def scene_save(self, *, path: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Save the scene as JSON (.sky.json). Path is relative to the project."""
        return await self._c.call('scene_save', _args(SceneSaveArgs, {'path': path}), check=check, timeout=timeout)

    async def selection_get(self, *, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Entities the human currently has selected in the editor ("this", "these" usually means them)."""
        return await self._c.call('selection_get', _args(SelectionGetArgs, {}), check=check, timeout=timeout)

    async def selection_set(self, *, entities: list[int | str], check: bool = False, timeout: float | None = None) -> ToolResult:
        """Select entities in the editor to show the human what you mean."""
        return await self._c.call('selection_set', _args(SelectionSetArgs, {'entities': entities}), check=check, timeout=timeout)

    async def sequence_camera_shot(self, *, sequence: Any, shot: Literal['orbit', 'dolly', 'crane', 'track', 'pan', 'static', 'path', 'flyover'], duration: float, camera: str | None = None, start: float | None = None, target: Any | None = None, offset: list[float] | None = None, radius: float | None = None, height: Any | None = None, distance: Any | None = None, angle: float | None = None, from_: Any | None = None, to: Any | None = None, position: list[float] | None = None, points: list[list[Any]] | None = None, pitch: float | None = None, fov: Any | None = None, roll: float | None = None, ease: Any | None = None, cut: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Add a procedural camera move to a sequence — the quickest way to direct cinematics. Shots are evaluated live each tick, so they follow moving targets. Kinds: orbit (around target; radius, height, from/to degrees), dolly (distance [far, near] along angle, or from/to points), crane (height [low, high]), track (side-on, slides from/to meters while following the target), pan (fixed position, look from/to: entities, points or yaw degrees), static (position looking at target), path (Catmull-Rom through points, looking at target or along the path), flyover (straight aerial pass over the target from the angle side: distance = half the pass length, height). fov: number or [from, to] (zoom), roll in degrees, ease (default smooth). cut=true (default) also switches to this camera at start. Missing cameras are created. Example: {"sequence": "Intro", "camera": "Cam A", "shot": "orbit", "target": "Hero", "start": 0, "duration": 5, "radius": 5, "height": 1.8, "from": -30, "to": 60}."""
        return await self._c.call('sequence_camera_shot', _args(SequenceCameraShotArgs, {'sequence': sequence, 'camera': camera, 'shot': shot, 'start': start, 'duration': duration, 'target': target, 'offset': offset, 'radius': radius, 'height': height, 'distance': distance, 'angle': angle, 'from': from_, 'to': to, 'position': position, 'points': points, 'pitch': pitch, 'fov': fov, 'roll': roll, 'ease': ease, 'cut': cut}), check=check, timeout=timeout)

    async def sequence_create(self, *, path: str, name: str | None = None, duration: float | None = None, tracks: list[dict[str, Any]] | None = None, entity: str | None = None, play_on_start: bool | None = None, loop: bool | None = None, overwrite: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Create a cinematic sequence asset (*.sequence.json) and an entity whose `sequencer` plays it when the simulation starts. Then add content with sequence_key (keyed properties, camera cuts, events, animations) and sequence_camera_shot (orbit / dolly / crane / track / pan / static / path / flyover moves), check frames with sequence_scrub and play with sequence_play. `tracks` may hold a full track list (see docs/ANIMATION.md). Example: {"path": "cinematics/intro.sequence.json", "duration": 10}."""
        return await self._c.call('sequence_create', _args(SequenceCreateArgs, {'path': path, 'name': name, 'duration': duration, 'tracks': tracks, 'entity': entity, 'play_on_start': play_on_start, 'loop': loop, 'overwrite': overwrite}), check=check, timeout=timeout)

    async def sequence_get(self, *, sequence: Any, time: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """A sequence's tracks (type, entity, property, key count and time span) and length; with `time`, the evaluated property values and live camera at that moment."""
        return await self._c.call('sequence_get', _args(SequenceGetArgs, {'sequence': sequence, 'time': time}), check=check, timeout=timeout)

    async def sequence_key(self, *, sequence: Any, keys: list[dict[str, Any]] | None = None, camera_cuts: list[dict[str, Any]] | None = None, events: list[dict[str, Any]] | None = None, animations: list[dict[str, Any]] | None = None, replace: bool | None = None, remove: list[dict[str, Any]] | None = None, duration: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Add or replace keys in a sequence, many at once. `keys`: property keys {entity, property, t, value, ease} animating any component field ("transform.position", "transform.rotation", "light.intensity", "light.color", "camera.fov", "mesh.color", "mesh.emissive", "particles.rate", or "environment.sunElevation" without entity). ease: linear (default), step, smooth, ease_in, ease_out, auto (smooth spline through neighbours — best for camera paths) or [x1,y1,x2,y2] cubic-bezier. `camera_cuts`: [{t, camera}] which camera is live. `events`: [{t, event, target?}] Wander events. `animations`: [{entity, t, play, fade?, loop?, params?}] drive animators. A key at an existing time replaces it; replace=true clears touched tracks first. Example: {"sequence": "cinematics/intro.sequence.json", "keys": [{"entity": "Sun", "property": "light.intensity", "t": 0, "value": 0}, {"entity": "Sun", "property": "light.intensity", "t": 3, "value": 4, "ease": "smooth"}]}."""
        return await self._c.call('sequence_key', _args(SequenceKeyArgs, {'sequence': sequence, 'keys': keys, 'camera_cuts': camera_cuts, 'events': events, 'animations': animations, 'replace': replace, 'remove': remove, 'duration': duration}), check=check, timeout=timeout)

    async def sequence_play(self, *, sequence: Any, action: Literal['play', 'stop'] | None = None, from_: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Play or stop a sequence. Sequences run in the simulation: while editing this starts the simulation (like sim_control play) and plays the sequence from `from`; while playing it restarts / seeks or stops it. Sequencers with playOnStart start by themselves when the simulation starts. Watch with viewport_capture view="scene" after sim_control step."""
        return await self._c.call('sequence_play', _args(SequencePlayArgs, {'sequence': sequence, 'action': action, 'from': from_}), check=check, timeout=timeout)

    async def sequence_scrub(self, *, sequence: Any, time: float | None = None, times: list[float] | None = None, fps: float | None = None, from_: float | None = None, to: float | None = None, save_dir: str | None = None, camera: Literal['sequence', 'editor'] | None = None, width: int | None = None, height: int | None = None, persist: bool | None = None, include_image: bool | None = None, transient: bool | None = None, clear: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Look at a sequence at any time without playing: renders through the sequence's live camera (cuts and shots) with every keyed property and animation applied, then restores the scene. times=[...] returns up to 8 images (a storyboard). Render a whole shot to disk with fps + from/to + save_dir (PNG frames, e.g. for a video). persist=true instead leaves the editor showing that time (sequencer preview). Only while editing. Example: {"sequence": "Intro", "times": [0, 2.5, 5]}."""
        return await self._c.call('sequence_scrub', _args(SequenceScrubArgs, {'sequence': sequence, 'time': time, 'times': times, 'fps': fps, 'from': from_, 'to': to, 'save_dir': save_dir, 'camera': camera, 'width': width, 'height': height, 'persist': persist, 'include_image': include_image, 'transient': transient, 'clear': clear}), check=check, timeout=timeout)

    async def shader_get(self, *, check: bool = False, timeout: float | None = None) -> ToolResult:
        """The renderer's current shader source (Metal Shading Language). Edit it with shader_set."""
        return await self._c.call('shader_get', _args(ShaderGetArgs, {}), check=check, timeout=timeout)

    async def shader_set(self, *, source: str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Replace the renderer's shader source at runtime. On a compile error nothing changes and the compiler diagnostics are returned. Function names and struct layouts must be kept."""
        return await self._c.call('shader_set', _args(ShaderSetArgs, {'source': source}), check=check, timeout=timeout)

    async def shadow_atlas_info(self, *, view: Any | None = None, entity: int | str | None = None, render: bool | None = None, invalidate: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Which point and spot lights cast shadows this frame and how: projection (spot view, cube = 6 views, dual_paraboloid = 2 views), atlas slot and resolution, whether it was re-rendered this frame or reused from the static cache, and why a light has no shadow (disabled, out_of_view, beyond_max_distance, over_light_budget, atlas_full, pending). Also the atlas size and memory, slots used per quadrant, the per-frame budgets (Environment.localShadowLights / localShadowUpdates) and warnings. Renders one real-time frame of `view` first (default: the editor camera). Use it when light leaks through walls, a shadow is missing or blocky, or to check the cost of many lamps; see the atlas itself with viewport_capture debug_view "shadow_atlas". With `entity`, also lists the meshes that block that light (casters, first 40) and the small fixtures right at the light that are ignored (lamp heads, bulbs). invalidate=true re-renders every cached shadow on the next frame. Example: {"view": "scene"} or {"entity": "Street Lamp 3"}."""
        return await self._c.call('shadow_atlas_info', _args(ShadowAtlasInfoArgs, {'view': view, 'entity': entity, 'render': render, 'invalidate': invalidate}), check=check, timeout=timeout)

    async def sim_control(self, *, action: Literal['play', 'pause', 'stop', 'step', 'status', 'pause_game', 'resume_game', 'time_scale'], ticks: int | None = None, scale: float | None = None, interpolation: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """play / pause / stop the game, or `step` N fixed ticks (1/60 s each) deterministically and get the resulting logs and errors. stop restores the scene to its pre-play state. Use step + viewport_capture to test behaviors. Two different pauses: `pause` is the EDITOR pause (nothing ticks; step still works), `pause_game` is the GAME's pause, like a pause menu (pause_game() in Wander): pausable entities freeze while UI canvases and `process` mode always/when_paused entities keep running, and `on pause` fires. `time_scale` with scale (0..10) is slow motion / fast forward for the game clock. Game pause and time scale apply from the next tick. `interpolation` turns render smoothing between ticks on/off (real-time frames only). Example: {"action":"pause_game"} then {"action":"step","ticks":30}."""
        return await self._c.call('sim_control', _args(SimControlArgs, {'action': action, 'ticks': ticks, 'scale': scale, 'interpolation': interpolation}), check=check, timeout=timeout)

    async def sim_input(self, *, press: list[str] | None = None, hold: list[str] | None = None, release: list[str] | None = None, actions: list[Any] | None = None, axes: list[dict[str, Any]] | None = None, release_actions: list[str] | None = None, gamepad: dict[str, Any] | None = None, mouse: dict[str, Any] | None = None, click: int | str | None = None, event: str | None = None, data: Any | None = None, target: int | str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Inject player input for the next ticks, like a player (or a playtest bot) would: press keys (fires `on key`), hold/release keys (for key()), press or hold input ACTIONS (jump, fire, ... see input_map; fires `on action`) for N ticks (60 ticks = 1 s), hold an axis at a value (move forward: axes=[{name:"move", x:0, y:1, ticks:120}]), set a simulated gamepad (sticks, triggers, buttons) or mouse (position, movement, buttons), click an entity (fires `on click`), or emit a named event. Applies on the next tick: follow with sim_control step."""
        return await self._c.call('sim_input', _args(SimInputArgs, {'press': press, 'hold': hold, 'release': release, 'actions': actions, 'axes': axes, 'release_actions': release_actions, 'gamepad': gamepad, 'mouse': mouse, 'click': click, 'event': event, 'data': data, 'target': target}), check=check, timeout=timeout)

    async def sim_teleport(self, *, entity: int | str, position: list[float] | None = None, rotation: list[float] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Move an entity instantly — a respawn, a portal, a checkpoint — without render interpolation smearing it across the screen for a frame (Wander: teleport(entity, position)). position/rotation are local (like transform). Without position/rotation it only resets the smoothing. Undoable."""
        return await self._c.call('sim_teleport', _args(SimTeleportArgs, {'entity': entity, 'position': position, 'rotation': rotation}), check=check, timeout=timeout)

    async def sim_trace(self, *, entities: list[int | str], properties: list[str], ticks: int | None = None, every: int | None = None, press: list[str] | None = None, hold: list[str] | None = None, restore: bool | None = None, display_hz: float | None = None, interpolation: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Run the game for N ticks and sample properties over time — e.g. transform.position of the player, vars.score, mesh.color — to verify behaviors numerically (did it jump? does the score increase?). Paths: <component>.<field>[.<sub>], vars.<name>, name, enabled. By default the scene is restored afterwards if it was in edit mode. display_hz (e.g. 120) simulates a real display instead: real time advances 1/display_hz per frame (fixed 60 Hz ticks accumulate), `every` counts display frames, and each sample shows the interpolation alpha plus `shown` = what that frame displays (render interpolation) next to the tick values; the result's `smoothness` compares how evenly vector properties move per frame with and without interpolation (stepJitter: 0 = perfectly even, about 2 = every other frame repeats a tick) and `pacing` gives the frame-time jitter."""
        return await self._c.call('sim_trace', _args(SimTraceArgs, {'entities': entities, 'properties': properties, 'ticks': ticks, 'every': every, 'press': press, 'hold': hold, 'restore': restore, 'display_hz': display_hz, 'interpolation': interpolation}), check=check, timeout=timeout)

    async def sprite_atlas_pack(self, *, folder: str | None = None, inputs: list[str] | None = None, output: str | None = None, padding: int | None = None, trim: bool | None = None, extrude: int | None = None, max_size: int | None = None, power_of_two: bool | None = None, fps: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Pack many images (a folder, a list, or globs like "sprites/hero/*.png") into one atlas texture plus a *.atlas.json describing every frame (trimmed of transparent borders, padded and edge-extruded so nothing bleeds). Frames are named after their files and keep natural order (run_2 before run_10). Sprites then use {"texture": "<atlas>.atlas.json", "frame": "run_3"}; the result suggests sprite_anim clips from numbered names (run_0..run_7 -> "run"). Example: {"folder": "art/hero", "output": "art/hero.atlas.json"}"""
        return await self._c.call('sprite_atlas_pack', _args(SpriteAtlasPackArgs, {'folder': folder, 'inputs': inputs, 'output': output, 'padding': padding, 'trim': trim, 'extrude': extrude, 'max_size': max_size, 'power_of_two': power_of_two, 'fps': fps}), check=check, timeout=timeout)

    async def sprite_sheet_slice(self, *, image: str, cell: list[int] | None = None, columns: int | None = None, rows: int | None = None, margin: int | None = None, spacing: int | None = None, prefix: str | None = None, names: list[str] | None = None, skip_empty: bool | None = None, output: str | None = None, animations: dict[str, Any] | None = None, entity: int | str | None = None, pixels_per_unit: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Describe a grid sprite sheet as an atlas (*.atlas.json) so frames get names: give the cell size (or columns/rows), optional margin/spacing, and either names or a prefix. `animations` turns rows (or index ranges) into sprite_anim clips, and `entity` applies the sprite and its animations to an entity in one step. Example: {"image": "art/knight.png", "cell": [32, 32], "animations": {"idle": {"row": 0, "fps": 6}, "run": {"row": 1, "fps": 12}, "attack": {"frames": "16-21", "fps": 14, "loop": false}}, "entity": "Knight"}"""
        return await self._c.call('sprite_sheet_slice', _args(SpriteSheetSliceArgs, {'image': image, 'cell': cell, 'columns': columns, 'rows': rows, 'margin': margin, 'spacing': spacing, 'prefix': prefix, 'names': names, 'skip_empty': skip_empty, 'output': output, 'animations': animations, 'entity': entity, 'pixels_per_unit': pixels_per_unit}), check=check, timeout=timeout)

    async def studio_agent_brief(self, *, agent: str, loop_member: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Everything needed to *be* a roster member: its system prompt (role mission, focus, persona, standing instructions, memory, the team, studio etiquette) and the engine tools it may use with their access (allow | ask). Use it to run a studio agent in any harness: e.g. give a Claude Code / Codex subagent this system prompt, let it call only the listed tools, and connect it as "<client>/<agent id>" (or pass as: "<agent id>") so its work is attributed. loop_member=true withholds loop and roster control tools."""
        return await self._c.call('studio_agent_brief', _args(StudioAgentBriefArgs, {'agent': agent, 'loop_member': loop_member}), check=check, timeout=timeout)

