        return await self._c.call('studio_decide', _args(StudioDecideArgs, {'feedback': feedback, 'verdict': verdict, 'rationale': rationale, 'tasks': tasks, 'task_ids': task_ids, 'merge_into': merge_into, 'targets': targets, 'metrics_before': metrics_before, 'redecide': redecide, 'as': as_}), check=check, timeout=timeout)

