    def studio_feedback_update(self, *, feedback: str, status: Literal['open', 'accepted', 'dropped', 'deferred', 'in_progress', 'fixed', 'verified', 'regressed'] | None = None, severity: Literal['low', 'medium', 'high', 'critical'] | None = None, category: Literal['fun', 'difficulty', 'clarity', 'visuals', 'audio', 'performance', 'bug', 'narrative', 'accessibility'] | None = None, summary: str | None = None, details: str | None = None, target: str | None = None, evidence: dict[str, Any] | None = None, comment: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Change a feedback item: status (e.g. verified after a critic's re-review, regressed to reopen its tasks), severity, category, summary, target, more evidence, or a comment for its history. Decisions themselves go through studio_decide."""
