    def studio_inbox(self, *, agent: str | None = None, unread_only: bool | None = None, channel: str | None = None, thread: str | None = None, after: str | None = None, limit: int | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Messages for you (addressed to you, mentioning you, or broadcast in #general), oldest first; unread only by default, and reading marks them read. Check it when you start a task. `channel` reads a whole channel; agent reads someone else's inbox without marking."""
