    def studio_loop_advance(self, *, loop: str, reports: list[dict[str, Any]] | None = None, approve: bool | None = None, signoff: bool | None = None, complete_stage: bool | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Report the results of a loop stage's assignments and move the loop on: reports [{agent, report, signoff?, usage?}]. When every pending assignment has reported (or complete_stage=true), the loop runs the following stages — playtests, verification, effect measurement — until it needs agents again, waits for approval, or ends on its stop conditions. Returns the new status with the next assignments. Directors sign off with signoff=true (or a report starting with SIGNOFF). approve=true/false answers a human approval gate."""
        return self._c.call('studio_loop_advance', _args(StudioLoopAdvanceArgs, {'loop': loop, 'reports': reports, 'approve': approve, 'signoff': signoff, 'complete_stage': complete_stage, 'as': as_}), check=check, timeout=timeout)

    def studio_loop_define(self, *, name: str | None = None, template: Literal['playtest_fix_verify', 'art_pass_with_critic', 'balance_tuning', 'vertical_slice_sprint', 'bug_bash'] | None = None, goal: str | None = None, description: str | None = None, stages: list[dict[str, Any]] | None = None, stop: dict[str, Any] | None = None, delete: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Define a studio loop: a repeatable cycle of stages with stop conditions, stored in studio/loops/<name>.loop.json. Start from a template (playtest_fix_verify, art_pass_with_critic, balance_tuning, vertical_slice_sprint, bug_bash) and override goal/stop, or write stages yourself. A stage is either kind "playtest" (the engine plays the game with bots: playtest {policy, runs, seconds}, file_feedback, verify_fixed) or kind "agents" (assignees: ["@role", "@discipline", "agent-id", "@a|@b" fallback], instruction template with {{goal}} {{inputs}} {{open_feedback}} {{my_tasks}} {{metrics}} {{roster}} {{iteration}}, parallel, only_with_tasks, gate {skip_if: no_open_feedback | no_todo_tasks | not_first_iteration | ..., approval: "human"}). stop: {max_iterations, metric_targets {completion_rate:{min:0.8}}, director_signoff, token_budget, time_budget_minutes}. delete=true removes it."""
        return self._c.call('studio_loop_define', _args(StudioLoopDefineArgs, {'name': name, 'template': template, 'goal': goal, 'description': description, 'stages': stages, 'stop': stop, 'delete': delete}), check=check, timeout=timeout)

    def studio_loop_start(self, *, loop: str, goal: str | None = None, max_iterations: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Start a run of a loop. The engine runs playtest stages itself and returns the first agent stage's assignments: [{agent, stage, prompt, tasks}]. Execute each assignment as that agent (in-editor crew, the headless runner `skywalker studio run`, or your own subagents with actor "<client>/<agent id>"; parallel=true means they may run at the same time), then report back with studio_loop_advance. Override goal or max_iterations for this run."""
        return self._c.call('studio_loop_start', _args(StudioLoopStartArgs, {'loop': loop, 'goal': goal, 'max_iterations': max_iterations}), check=check, timeout=timeout)

    def studio_loop_status(self, *, loop: str | None = None, history: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """A loop's state: status, iteration, current stage, pending assignments (with prompts), per-iteration history (stage reports, playtests, filed feedback, verified effects) and metric trends. Without a loop name, lists every loop and the available templates."""
        return self._c.call('studio_loop_status', _args(StudioLoopStatusArgs, {'loop': loop, 'history': history}), check=check, timeout=timeout)

    def studio_loop_stop(self, *, loop: str, reason: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Stop a running loop (pending assignments are dropped)."""
        return self._c.call('studio_loop_stop', _args(StudioLoopStopArgs, {'loop': loop, 'reason': reason}), check=check, timeout=timeout)

    def studio_memory(self, *, action: Literal['note', 'forget', 'list'], text: str | None = None, number: int | None = None, agent: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Your long-term memory as a studio agent (kept in your profile and shown at the start of every task): note a fact worth remembering (conventions, decisions, the human's preferences, unfinished work), forget an outdated note by number, or list notes."""
        return self._c.call('studio_memory', _args(StudioMemoryArgs, {'action': action, 'text': text, 'number': number, 'agent': agent, 'as': as_}), check=check, timeout=timeout)

    def studio_message_send(self, *, text: str, to: list[str] | None = None, channel: str | None = None, reply_to: str | None = None, task: str | None = None, feedback: str | None = None, kind: str | None = None, data: dict[str, Any] | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Talk to the team so the back-and-forth is visible: post in a channel (#general by default; any name creates a channel), address agents with `to` or @mentions in the text (@id, @role, @discipline, @all), reply in a thread with reply_to, and reference a task/feedback. Example: {text:"@lighting_artist the lava needs a stronger glow, see F-2", feedback:"F-2"}."""
        return self._c.call('studio_message_send', _args(StudioMessageSendArgs, {'text': text, 'to': to, 'channel': channel, 'reply_to': reply_to, 'task': task, 'feedback': feedback, 'kind': kind, 'data': data, 'as': as_}), check=check, timeout=timeout)

    def studio_overview(self, *, include_catalog: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Start here when working with the studio (a team of AI agents making this game). Returns the roster with live status, the task board counts, feedback waiting for a decision, recent director decisions with measured effects, loops and their state, the latest playtest metrics, and token/cost usage. include_catalog=true also lists roles, disciplines, team templates and loop templates."""
        return self._c.call('studio_overview', _args(StudioOverviewArgs, {'include_catalog': include_catalog}), check=check, timeout=timeout)

    def studio_presence(self, *, status: Literal['working', 'idle', 'waiting', 'blocked'], activity: str | None = None, agent: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Show what a roster member is doing right now in the editor's Studio panel (live status and activity next to its avatar): working with a one-line activity when you start something, idle when you finish. External harnesses (the Python agent layer, scripts, Claude Code subagents) call it so their agents appear live like the editor's crew. Example: {status: "working", activity: "T-4 widen the lava bridge", as: "mira"}."""
        return self._c.call('studio_presence', _args(StudioPresenceArgs, {'status': status, 'activity': activity, 'agent': agent, 'as': as_}), check=check, timeout=timeout)

    def studio_task_claim(self, *, task: str | None = None, agent: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Claim a task and start it (assignee = you, status = doing). Without `task`, claims your highest-priority todo task, or else an unassigned todo task in your discipline. External agents identify with `as` or a client name ending in /<agent id>."""
        return self._c.call('studio_task_claim', _args(StudioTaskClaimArgs, {'task': task, 'agent': agent, 'as': as_}), check=check, timeout=timeout)

    def studio_task_create(self, *, title: str, description: str | None = None, acceptance: list[str] | None = None, discipline: Literal['direction', 'production', 'design', 'engineering', 'art', 'audio', 'writing', 'qa'] | None = None, assignee: str | None = None, priority: Literal['low', 'normal', 'high', 'critical'] | None = None, status: Literal['backlog', 'todo', 'doing', 'review', 'done', 'dropped'] | None = None, depends_on: list[str] | None = None, feedback: list[str] | None = None, links: dict[str, Any] | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Put a task on the studio board. Good tasks are small and checkable: a clear title, acceptance criteria (how we know it's done), a discipline, and an assignee (agent id, or "@role" to pick the least busy agent with that role). Link the feedback it addresses so the effect can be measured. Example: {title:"Widen the lava bridge", acceptance:["bridge 3 m wide","deaths ≤ 1 per run"], assignee:"@level_designer", feedback:["F-2"]}."""
        return self._c.call('studio_task_create', _args(StudioTaskCreateArgs, {'title': title, 'description': description, 'acceptance': acceptance, 'discipline': discipline, 'assignee': assignee, 'priority': priority, 'status': status, 'depends_on': depends_on, 'feedback': feedback, 'links': links, 'as': as_}), check=check, timeout=timeout)

    def studio_task_list(self, *, status: str | None = None, assignee: str | None = None, discipline: str | None = None, mine: bool | None = None, limit: int | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """The studio board. Filter by status (or "open" = backlog/todo/doing/review), assignee, discipline, or mine=true for your own tasks. Returns tasks with acceptance criteria, links and comment counts; the text is a compact kanban."""
        return self._c.call('studio_task_list', _args(StudioTaskListArgs, {'status': status, 'assignee': assignee, 'discipline': discipline, 'mine': mine, 'limit': limit, 'as': as_}), check=check, timeout=timeout)

    def studio_task_update(self, *, task: str, status: Literal['backlog', 'todo', 'doing', 'review', 'done', 'dropped'] | None = None, assignee: str | None = None, priority: Literal['low', 'normal', 'high', 'critical'] | None = None, title: str | None = None, description: str | None = None, acceptance: list[str] | None = None, discipline: str | None = None, depends_on: list[str] | None = None, links: dict[str, Any] | None = None, comment: str | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Move a task across the board (backlog → todo → doing → review → done, or dropped), reassign it, edit it, or add a comment. Marking the last task of a feedback item done moves that feedback to "fixed" (the next verification playtest then measures the effect). Moving to doing/done checks dependencies."""
        return self._c.call('studio_task_update', _args(StudioTaskUpdateArgs, {'task': task, 'status': status, 'assignee': assignee, 'priority': priority, 'title': title, 'description': description, 'acceptance': acceptance, 'discipline': discipline, 'depends_on': depends_on, 'links': links, 'comment': comment, 'as': as_}), check=check, timeout=timeout)

    def studio_team_template(self, *, template: Literal['starter_crew', 'indie_trio', 'aaa_strike_team', 'narrative_team', 'qa_squad', 'art_team', 'audio_team'], defaults: dict[str, Any] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Spawn a whole team of specialists from a template (agents that already exist by id are updated): starter_crew (5 generalists), indie_trio (3), aaa_strike_team (22: director, producer, five designers, four programmers, five artists, audio, writing, QA, two playtester personas, critic), narrative_team, qa_squad (QA lead, three playtester personas, critic, fixer), art_team, audio_team. Override provider/model/autonomy for everyone with `defaults`."""
        return self._c.call('studio_team_template', _args(StudioTeamTemplateArgs, {'template': template, 'defaults': defaults}), check=check, timeout=timeout)

    def studio_usage_report(self, *, agent: str | None = None, model: str | None = None, input_tokens: int | None = None, output_tokens: int | None = None, cache_read_tokens: int | None = None, cache_write_tokens: int | None = None, as_: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Record tokens an agent spent with its own model, for studio budgets and cost tracking (runners that call models outside the engine — the editor crew, custom scripts — report each request here). Tool calls are counted automatically."""
        return self._c.call('studio_usage_report', _args(StudioUsageReportArgs, {'agent': agent, 'model': model, 'input_tokens': input_tokens, 'output_tokens': output_tokens, 'cache_read_tokens': cache_read_tokens, 'cache_write_tokens': cache_write_tokens, 'as': as_}), check=check, timeout=timeout)

    def terrain_create(self, *, name: str | None = None, preset: Literal['island_beach', 'tropical_coast', 'alpine', 'canyon', 'desert_dunes', 'rolling_hills', 'mountain_valley', 'flat'] | None = None, size: float | None = None, resolution: int | None = None, position: list[float] | None = None, seed: int | None = None, generator: dict[str, Any] | None = None, layers: list[Any] | None = None, heightmap: str | None = None, water: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Create a large heightfield terrain: an island with beaches, a tropical coast, alpine peaks, a canyon, desert dunes, rolling hills or a mountain valley. Natural shapes come from warped noise plus hydraulic and thermal erosion; material layers (sand, grass, soil, rock, snow...) are auto-painted by height and slope, with procedural textures unless you pass your own layer textures (e.g. downloaded photoscans). `water: true` adds an FFT sea at sea level and wet sand along the shore. Then add foliage_add (grass, pebbles, shells, rocks). Your own relief: pass `heightmap` (a grayscale PNG). Examples: {"preset":"island_beach","size":600,"water":true}, {"heightmap":"maps/continent.png","size":4000,"generator":{"minHeight":-40,"maxHeight":160}}."""
        return self._c.call('terrain_create', _args(TerrainCreateArgs, {'name': name, 'preset': preset, 'size': size, 'resolution': resolution, 'position': position, 'seed': seed, 'generator': generator, 'layers': layers, 'heightmap': heightmap, 'water': water}), check=check, timeout=timeout)

    def terrain_generate(self, *, entity: int | str, generator: dict[str, Any] | None = None, seed: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Regenerate a terrain's heights from new generator parameters (shape, seed, heights, featureSize, ridges, warp, erosion, thermal, terraces, beachWidth, seaLevel), then re-paint its layers. Undo with terrain_undo."""
        return self._c.call('terrain_generate', _args(TerrainGenerateArgs, {'entity': entity, 'generator': generator, 'seed': seed}), check=check, timeout=timeout)

    def terrain_layers(self, *, entity: int | str, layers: list[Any], auto_paint: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Replace a terrain's material layers and re-paint them from their rules (height/slope/noise). Each layer: {name, texture, normalMap, ormMap (project paths, e.g. downloaded photoscans) or texgen (sand, grass, dirt, rock, noise), color/tint, roughness, tiling (meters per repeat), triplanar (cliffs), heightMin, heightMax, slopeMin, slopeMax, noise, sharpness}. Base layer first; later layers paint over earlier ones where their rules match. Hand-painted weights are replaced unless auto_paint is false."""
        return self._c.call('terrain_layers', _args(TerrainLayersArgs, {'entity': entity, 'layers': layers, 'auto_paint': auto_paint}), check=check, timeout=timeout)

    def terrain_paint(self, *, entity: int | str, layer: Any, strokes: list[dict[str, Any]], check: bool = False, timeout: float | None = None) -> ToolResult:
        """Paint a material layer (by index or name) onto a terrain with brush strokes at world (x, z): sand paths, dirt patches, grass clearings. Foliage restricted to a layer follows the paint. Undo with terrain_undo."""
        return self._c.call('terrain_paint', _args(TerrainPaintArgs, {'entity': entity, 'layer': layer, 'strokes': strokes}), check=check, timeout=timeout)

    def terrain_query(self, *, entity: int | str | None = None, points: list[list[float]] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Terrain height, normal, slope (degrees) and dominant layer at world (x, z) points, plus terrain stats. Use it to place villages on flat ground, find the shoreline, or check where cliffs are."""
        return self._c.call('terrain_query', _args(TerrainQueryArgs, {'entity': entity, 'points': points}), check=check, timeout=timeout)

    def terrain_sculpt(self, *, entity: int | str, strokes: list[dict[str, Any]], check: bool = False, timeout: float | None = None) -> ToolResult:
        """Sculpt a terrain with brush strokes at world (x, z) positions: raise / lower (strength in meters), flatten (toward `target` world height; plateaus, roads, building pads), smooth, noise (rougher ground), set. Great for carving a beach cove, a path, a harbor basin or a flat spot for a village. Undo with terrain_undo."""
        return self._c.call('terrain_sculpt', _args(TerrainSculptArgs, {'entity': entity, 'strokes': strokes}), check=check, timeout=timeout)

    def terrain_undo(self, *, entity: int | str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Step back the last terrain_sculpt / terrain_paint / terrain_generate / terrain_layers on a terrain (heights and weights; component fields use the regular undo)."""
        return self._c.call('terrain_undo', _args(TerrainUndoArgs, {'entity': entity}), check=check, timeout=timeout)

    def texture_generate(self, *, kind: Literal['noise', 'marble', 'wood', 'planks', 'bricks', 'tiles', 'cobblestone', 'grass', 'dirt', 'sand', 'rock', 'metal_brushed', 'rust', 'fabric', 'checker', 'stripes', 'hexagons', 'scales', 'stylized', 'glow', 'curtain'], name: str, size: int | None = None, seed: int | None = None, scale: float | None = None, color1: str | None = None, color2: str | None = None, color3: str | None = None, roughness: float | None = None, metallic: float | None = None, variation: float | None = None, bump: float | None = None, create_material: bool | None = None, tiling: float | None = None, glow: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Procedurally generate a seamless PBR texture set — albedo, normal map and ORM (occlusion/roughness/metallic) — for realistic or stylized surfaces: bricks, planks, cobblestone, rock, rust, marble, fabric, scales, ... With create_material it also writes a ready material (triplanar by default, so it works on scaled primitives without stretching). Colors override the kind's defaults. The soft kinds `glow` (radial) and `curtain` (vertical rays fading upward) have transparent edges and make self-lit effect materials: particles, light pools, fake reflections, auroras, light shafts, steam."""
        return self._c.call('texture_generate', _args(TextureGenerateArgs, {'kind': kind, 'name': name, 'size': size, 'seed': seed, 'scale': scale, 'color1': color1, 'color2': color2, 'color3': color3, 'roughness': roughness, 'metallic': metallic, 'variation': variation, 'bump': bump, 'create_material': create_material, 'tiling': tiling, 'glow': glow}), check=check, timeout=timeout)

    def tilemap_from_ascii(self, *, map: str, legend: dict[str, Any], entity: int | str | None = None, name: str | None = None, layer: str | None = None, tileset: str | None = None, tile_size: int | None = None, cell_size: float | None = None, position: list[float] | None = None, autotile: dict[str, Any] | None = None, solid: bool | str | None = None, solid_tiles: list[Any] | str | None = None, sorting_layer: Literal['background', 'midground', 'default', 'foreground', 'overlay'] | None = None, z: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Build or update a tilemap from an ASCII map — the fastest way to lay out a level. Each line is a row (top first); `legend` maps characters to tile ids, terrain names (auto-tiled) or tileset tile names; ' ' and '.' are empty unless the legend says otherwise. Creates the entity if it doesn't exist. Without a tileset, tiles render as flat colors so you can block out levels before the art exists. `solid` marks this layer for collision (true = every tile, "tiles" = only solidTiles). Example: {"name": "Level", "tileset": "art/tiles.png", "tile_size": 16, "autotile": {"ground": {"mode": "blob47", "first": 1}}, "legend": {"#": "ground", "^": 60}, "solid": true, "map": "..........\\n...^^.....\\n##########"}"""
        return self._c.call('tilemap_from_ascii', _args(TilemapFromAsciiArgs, {'map': map, 'legend': legend, 'entity': entity, 'name': name, 'layer': layer, 'tileset': tileset, 'tile_size': tile_size, 'cell_size': cell_size, 'position': position, 'autotile': autotile, 'solid': solid, 'solid_tiles': solid_tiles, 'sorting_layer': sorting_layer, 'z': z}), check=check, timeout=timeout)

    def tilemap_inspect(self, *, entity: int | str, layer: str | None = None, max_rects: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Read a tilemap as ASCII per layer (with a legend of tile ids and counts), its size, tileset, terrains and the merged collision rectangles (world units, relative to the map's top-left; x right, y up) — what a physics body or a pathfinder needs."""
        return self._c.call('tilemap_inspect', _args(TilemapInspectArgs, {'entity': entity, 'layer': layer, 'max_rects': max_rects}), check=check, timeout=timeout)

    def tilemap_paint(self, *, entity: int | str, action: Literal['set', 'fill', 'flood', 'clear'], layer: str | None = None, tile: int | str | None = None, cells: list[list[int]] | None = None, rect: list[int] | None = None, at: list[int] | None = None, flip_x: bool | None = None, flip_y: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Edit a tilemap layer: set individual cells, fill a rectangle, flood-fill a region, or clear. `tile` is a tile id (1-based in the tileset, 0 = empty), a terrain from tilemap.autotile (auto-tiled: edges and corners pick the right tiles), or a tileset tile name. Cells are [column, row] from the top-left. One undo step. Example: {"entity": "Level", "action": "fill", "rect": [0, 14, 40, 2], "tile": "ground"}"""
        return self._c.call('tilemap_paint', _args(TilemapPaintArgs, {'entity': entity, 'layer': layer, 'action': action, 'tile': tile, 'cells': cells, 'rect': rect, 'at': at, 'flip_x': flip_x, 'flip_y': flip_y}), check=check, timeout=timeout)

    def tool_approve(self, *, name: str, approve: bool | None = None, note: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """A HUMAN approves (or rejects with approve:false) the current definition of a custom tool that needs approval (it mutates, writes files or reaches the network, or the policy is "ask"). The approval is bound to the definition's hash: changing the tool needs approval again. Agents cannot approve; ask the human to use the editor's Studio > Tools panel or `skywalker call tool_approve '{"name":"user_x"}' --project DIR`."""
        return self._c.call('tool_approve', _args(ToolApproveArgs, {'name': name, 'approve': approve, 'note': note}), check=check, timeout=timeout)

    def tool_define(self, *, name: str | None = None, title: str | None = None, description: str | None = None, category: str | None = None, kind: Literal['wander', 'composite'] | None = None, input_schema: dict[str, Any] | None = None, output_schema: dict[str, Any] | None = None, capabilities: dict[str, Any] | None = None, limits: dict[str, Any] | None = None, wander: str | None = None, steps: list[dict[str, Any]] | None = None, result: Any | None = None, tests: list[dict[str, Any]] | None = None, enabled: bool | None = None, from_library: str | None = None, run_tests: bool | None = None, validate_only: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Create or update your OWN tool when no engine tool does what you need. Kinds: "wander" — Wander code `fn run(args) ... end` that queries the scene and calls allowlisted tools (call_tool) under an instruction budget; "composite" — a pipeline of tool calls with templated args ({{args.x}}, {{steps.find.entities}}), for_each loops and a result mapping. Declare capabilities (read_scene, mutate, calls, files) as a minimal allowlist and add tests (args -> expect) — they run as dry runs before saving. Read-only tools become callable at once (as user_<name>, listed in tools/list); tools that mutate or write files wait for a human's approval (tool_approve) under the default policy. Updating merges your fields over the current definition. Example: {"name":"enemies_near","description":"Enemies within a radius of a point with their hp...","input_schema":{"type":"object","properties":{"radius":{"type":"number","default":10}}},"wander":"fn run(args)\\n  let out = []\\n  for e in find_all(\\"enemy\\")\\n    if distance(e, (0,0,0)) <= args.radius then out.push({name: e.name, hp: e.hp}) end\\n  end\\n  return {enemies: out}\\nend","tests":[{"args":{"radius":5},"expect":{"result":{"enemies":{"$type":"array"}}}}]}. docs/CUSTOM_TOOLS.md has recipes."""
        return self._c.call('tool_define', _args(ToolDefineArgs, {'name': name, 'title': title, 'description': description, 'category': category, 'kind': kind, 'input_schema': input_schema, 'output_schema': output_schema, 'capabilities': capabilities, 'limits': limits, 'wander': wander, 'steps': steps, 'result': result, 'tests': tests, 'enabled': enabled, 'from_library': from_library, 'run_tests': run_tests, 'validate_only': validate_only}), check=check, timeout=timeout)

    def tool_enable(self, *, name: str, enabled: bool, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Turn a custom tool off (it disappears from tools/list but keeps its files and approval) or back on."""
        return self._c.call('tool_enable', _args(ToolEnableArgs, {'name': name, 'enabled': enabled}), check=check, timeout=timeout)

    def tool_host_list(self, *, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Which external processes serve py_* tools: each host's label, owner (actor), tools, queued and in-flight calls, calls served and seconds since its last poll; plus the event stream's cursor range (events_poll)."""
        return self._c.call('tool_host_list', _args(ToolHostListArgs, {}), check=check, timeout=timeout)

    def tool_host_poll(self, *, host: str, wait_ms: int | None = None, max: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Fetch the calls other agents made to your py_* tools (see tool_host_register): [{call, tool, args, actor}]. wait_ms long-polls until a call arrives (default 20000, max 25000); use a connection dedicated to polling. Answer every call with tool_host_reply. Polling also keeps your host alive."""
        return self._c.call('tool_host_poll', _args(ToolHostPollArgs, {'host': host, 'wait_ms': wait_ms, 'max': max}), check=check, timeout=timeout)

    def tool_host_register(self, *, tools: list[dict[str, Any]], host: str | None = None, label: str | None = None, ttl_seconds: float | None = None, replace: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Offer tools implemented in your own process (a Python agent harness, a script) to every agent connected to this engine: each becomes an engine tool named py_<name> that appears in tools/list. Calls are queued for you; fetch them with tool_host_poll on a dedicated connection and answer each with tool_host_reply. Keep polling: a host that has not polled for ttl_seconds (default 60) is dropped with its tools. Re-register with the returned host id to change the tool set. Example: {label: "sky-agents memory", tools: [{name: "memory_recall", description: "Search the team's shared memory", input_schema: {type: "object", properties: {query: {type: "string"}}, required: ["query"]}}]}."""
        return self._c.call('tool_host_register', _args(ToolHostRegisterArgs, {'tools': tools, 'host': host, 'label': label, 'ttl_seconds': ttl_seconds, 'replace': replace}), check=check, timeout=timeout)

    def tool_host_reply(self, *, host: str, call: int, text: str | None = None, structured: dict[str, Any] | None = None, images: list[str] | None = None, is_error: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Answer one call fetched with tool_host_poll. Give text (what the calling model reads), optionally structured JSON and PNG images (base64), and is_error=true when the call failed (say why in text, with a hint)."""
        return self._c.call('tool_host_reply', _args(ToolHostReplyArgs, {'host': host, 'call': call, 'text': text, 'structured': structured, 'images': images, 'is_error': is_error}), check=check, timeout=timeout)

    def tool_host_unregister(self, *, host: str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Stop serving the py_* tools of a host (they disappear from tools/list; calls still waiting fail). Hosts that stop polling expire on their own after ttl_seconds."""
        return self._c.call('tool_host_unregister', _args(ToolHostUnregisterArgs, {'host': host}), check=check, timeout=timeout)

    def tool_inspect(self, *, name: str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Full definition of a custom tool: code or steps, schemas, capabilities, limits, tests, status and why, approval (by whom, for which hash), stats (calls, failures, timing) and its recent calls and errors. Use it to debug a tool or before changing it."""
        return self._c.call('tool_inspect', _args(ToolInspectArgs, {'name': name}), check=check, timeout=timeout)

    def tool_list_custom(self, *, include_library: bool | None = None, reload: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Every custom tool of the project (and external tools hosted by connected clients) with its status — active, pending_approval, rejected, disabled, offline, invalid — kind, version, author and call counts, plus the project's policy. include_library lists your user library (tool_promote); reload rescans tools/ for hand-edited definitions."""
        return self._c.call('tool_list_custom', _args(ToolListCustomArgs, {'include_library': include_library, 'reload': reload}), check=check, timeout=timeout)

    def tool_policy(self, *, policy: Literal['off', 'ask', 'auto', 'trust'] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Read or set who approves custom tools in this project (game.json customTools.policy): off (disabled), ask (every tool needs a human's approval), auto (default: read-only tools run at once, tools that mutate or write files need approval), trust (no approvals). Agents may only make it stricter."""
        return self._c.call('tool_policy', _args(ToolPolicyArgs, {'policy': policy}), check=check, timeout=timeout)

    def tool_promote(self, *, name: str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Copy a project's custom tool into your user library (~/.skywalker/tools) so other projects can install it with tool_define {"from_library": "user_x"} (their approval rules apply)."""
        return self._c.call('tool_promote', _args(ToolPromoteArgs, {'name': name}), check=check, timeout=timeout)

    def tool_remove(self, *, name: str, delete_files: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Unregister a custom tool and delete its files (tools/<name>.tool.json and .wander) unless delete_files is false. External tools are unregistered until their client registers them again."""
        return self._c.call('tool_remove', _args(ToolRemoveArgs, {'name': name, 'delete_files': delete_files}), check=check, timeout=timeout)

    def tool_test(self, *, name: str | None = None, definition: dict[str, Any] | None = None, args: dict[str, Any] | None = None, setup: list[dict[str, Any]] | None = None, filter: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Run a custom tool's tests, or one call with "args", as a DRY RUN: scene edits are rolled back and file writes skipped, so it is safe on tools that are not approved yet. Pass "definition" (same fields as tool_define) to try a draft without saving it. Returns per-test pass/fail with the compared values, logs and timing. Example: {"name":"user_enemies_near","args":{"radius":8}}"""
        return self._c.call('tool_test', _args(ToolTestArgs, {'name': name, 'definition': definition, 'args': args, 'setup': setup, 'filter': filter}), check=check, timeout=timeout)

    def transform(self, *, entity: int | str, position: list[float] | None = None, rotation: list[float] | None = None, scale: list[float] | None = None, translate: list[float] | None = None, rotate: list[float] | None = None, space: Literal['local', 'world'] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Move/rotate/scale an entity. Absolute: position, rotation (degrees), scale. Relative: translate, rotate. space=world interprets position in world space even if the entity has a parent."""
        return self._c.call('transform', _args(TransformArgs, {'entity': entity, 'position': position, 'rotation': rotation, 'scale': scale, 'translate': translate, 'rotate': rotate, 'space': space}), check=check, timeout=timeout)

    def ui_create(self, *, root: dict[str, Any] | None = None, elements: list[dict[str, Any]] | None = None, template: Literal['main_menu', 'hud', 'pause_menu', 'settings', 'inventory', 'document', 'dialogue'] | None = None, parent: int | str | None = None, canvas: dict[str, Any] | None = None, width: int | None = None, height: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Build a whole user interface (HUD, menu, dialog, inventory, document) from one declarative JSON tree in a single undoable step. Each node: {type: panel|image|text|button|toggle|slider|progress|scroll|input|spacer, name, text, image, style (classes, e.g. "primary large"), css (inline style), anchor (top_left, top, top_right, left, center, right, bottom_left, bottom, bottom_right, fill, top_stretch, bottom_stretch, left_stretch, right_stretch...), position [x,y] (offset, y down), size [w,h], margin, layout (row|column|grid), gap, padding (CSS order), align (start|center|end|stretch), justify (start|center|end|space_between), columns, fit (none|width|height|both), flex, value, event, children: [...]}. Text nodes size to their content by default; button names default to their text, so `on ui "Play"` works. Without `parent` a new screen canvas is made (configure it with `canvas`). Templates: main_menu, hud, pause_menu, settings, inventory, document, dialogue (the dialogue box the dialogue system uses). Returns created ids and the computed layout (rects in pixels at the canvas's reference resolution). Example: {"root": {"type": "panel", "anchor": "center", "layout": "column", "gap": 12, "style": "card", "children": [{"type": "text", "text": "Paused", "style": "heading"}, {"type": "button", "text": "Resume", "style": "primary"}]}}"""
        return self._c.call('ui_create', _args(UiCreateArgs, {'root': root, 'elements': elements, 'template': template, 'parent': parent, 'canvas': canvas, 'width': width, 'height': height}), check=check, timeout=timeout)

    def ui_inspect(self, *, canvas: int | str | None = None, element: int | str | None = None, width: int | None = None, height: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Read the computed UI layout: every element's rect [x, y, w, h] in pixels for a viewport (default: the canvas's reference resolution), visibility, text, values and style classes, as a tree. Use it to verify a layout without a screenshot, find what to click, or debug overlap. With `element`, also returns its resolved style."""
        return self._c.call('ui_inspect', _args(UiInspectArgs, {'canvas': canvas, 'element': element, 'width': width, 'height': height}), check=check, timeout=timeout)

    def ui_interact(self, *, element: int | str | None = None, at: list[float] | None = None, width: int | None = None, height: int | None = None, action: Literal['click', 'set_value', 'type', 'scroll', 'focus'] | None = None, value: float | None = None, text: str | None = None, append: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Use a widget the way a player would: click a button (sends Wander `on ui "<name>"` and `on click` on the next tick while playing), toggle, set a slider/progress value, type into an input, scroll a scroll view, or click at a pixel (hit-tested like a mouse). While editing, value changes are recorded edits and clicks only report which events would fire. Example: {"element": "Play", "action": "click"} then sim_control step."""
        return self._c.call('ui_interact', _args(UiInteractArgs, {'element': element, 'at': at, 'width': width, 'height': height, 'action': action, 'value': value, 'text': text, 'append': append}), check=check, timeout=timeout)

    def ui_style(self, *, canvas: int | str | None = None, theme: Literal['dark', 'light', 'parchment', 'glass', 'pixel'] | None = None, path: str | None = None, rules: dict[str, Any] | None = None, vars: dict[str, Any] | None = None, element: int | str | None = None, style: str | None = None, css: dict[str, Any] | None = None, list_: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Restyle a UI. Switch a canvas's built-in theme (dark, light, parchment, glass, pixel), write style rules to a style sheet (*.uistyle.json) the canvas uses — rules map selectors (widget kind "button", class ".primary", entity "#Title", "canvas" for text defaults) to properties, with hover/pressed/focus/checked/disabled blocks and $vars — or set one element's classes / inline css. Properties: background, background2 (gradient), backgroundImage, slice (9-slice), radius, borderWidth, borderColor, shadowColor, shadowOffset, shadowBlur, opacity, padding, font, fontSize, color, textAlign, verticalAlign, bold, italic, lineSpacing, letterSpacing, textTransform, textOutline, textOutlineColor, textShadowColor, textShadowOffset, accent, track, knob, trackHeight, knobSize, placeholderColor, imageFit, imageTint, transition. Example: {"canvas": "HUD", "path": "ui/game.uistyle.json", "vars": {"accent": "#e8a33d"}, "rules": {"button": {"radius": 4, "hover": {"background": "$accent"}}}}"""
        return self._c.call('ui_style', _args(UiStyleArgs, {'canvas': canvas, 'theme': theme, 'path': path, 'rules': rules, 'vars': vars, 'element': element, 'style': style, 'css': css, 'list': list_}), check=check, timeout=timeout)

    def viewport_capture(self, *, width: int | None = None, height: int | None = None, view: Literal['editor', 'scene'] | None = None, camera_entity: int | str | None = None, eye: list[float] | None = None, target: list[float] | None = None, fov: float | None = None, aperture: float | None = None, focus_distance: float | None = None, tilt_shift: float | None = None, annotate: bool | None = None, overlays: bool | None = None, samples: int | None = None, clay: bool | None = None, debug_view: Literal['final', 'albedo', 'normals', 'material', 'gi', 'reflections', 'ao', 'depth', 'lighting', 'sketch', 'impostors', 'wireframe', 'overdraw', 'unshaded', 'lighting_only', 'shadow_cascades', 'light_complexity', 'lod', 'emission', 'specular', 'uv_checker', 'texel_density', 'motion', 'shadow_atlas', 'reflection_probes'] | None = None, quality: Literal['full', 'balanced', 'fast'] | None = None, include_image: bool | None = None, save_path: str | None = None, alpha: float | None = None, frame_handlers: bool | None = None, probe: int | str | None = None, probe_mip: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Render the scene and return a PNG plus every visible entity with its on-screen box [x, y, w, h]. annotate=true (default) draws each entity's #id on the image so you can match what you see to ids. Choose the view: the editor camera (default), the game camera (view="scene"), or any eye/target. probe=<entity> returns that reflection probe's captured cubemap instead (6 faces as a cross)."""
        return self._c.call('viewport_capture', _args(ViewportCaptureArgs, {'width': width, 'height': height, 'view': view, 'camera_entity': camera_entity, 'eye': eye, 'target': target, 'fov': fov, 'aperture': aperture, 'focus_distance': focus_distance, 'tilt_shift': tilt_shift, 'annotate': annotate, 'overlays': overlays, 'samples': samples, 'clay': clay, 'debug_view': debug_view, 'quality': quality, 'include_image': include_image, 'save_path': save_path, 'alpha': alpha, 'frame_handlers': frame_handlers, 'probe': probe, 'probe_mip': probe_mip}), check=check, timeout=timeout)

    def viewport_debug_view(self, *, view: Literal['final', 'albedo', 'normals', 'material', 'gi', 'reflections', 'ao', 'depth', 'lighting', 'sketch', 'impostors', 'wireframe', 'overdraw', 'unshaded', 'lighting_only', 'shadow_cascades', 'light_complexity', 'lod', 'emission', 'specular', 'uv_checker', 'texel_density', 'motion', 'shadow_atlas', 'reflection_probes'] | None = None, list_: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Show a debug visualization in the live editor viewport (the human sees it too), or list every view with its color legend (list=true). Views: wireframe, overdraw, unshaded, lighting_only, shadow_cascades, light_complexity, lod, emission, specular, uv_checker, texel_density, plus the buffers albedo, normals, material, gi, reflections, ao, depth, lighting and sketch/impostors. "final" turns it off. For a one-off image use viewport_capture {debug_view}. Example: {"view": "overdraw"}."""
        return self._c.call('viewport_debug_view', _args(ViewportDebugViewArgs, {'view': view, 'list': list_}), check=check, timeout=timeout)

    def viewport_multi(self, *, focus: int | str | None = None, size: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """One image with four views of the scene (or an entity): perspective (top-left), top (top-right), front (bottom-left) and side (bottom-right). Orthographic views make layout, alignment and spacing problems obvious — use it to check level layouts."""
        return self._c.call('viewport_multi', _args(ViewportMultiArgs, {'focus': focus, 'size': size}), check=check, timeout=timeout)

    def viewport_pick(self, *, x: float, y: float, width: int | None = None, height: int | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Which entity is at pixel (x, y) of a capture with the given size (editor camera). Use with the boxes/annotations from viewport_capture."""
        return self._c.call('viewport_pick', _args(ViewportPickArgs, {'x': x, 'y': y, 'width': width, 'height': height}), check=check, timeout=timeout)

    def viewport_quality(self, *, quality: Literal['fast', 'balanced', 'full'] | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """How the live editor viewport renders while editing: fast (default; lower internal resolution, no screen-space GI/reflections or light shafts, near foliage shadows, coarser LODs) keeps heavy worlds responsive; balanced; full (what the game and captures show). Play mode always renders full."""
        return self._c.call('viewport_quality', _args(ViewportQualityArgs, {'quality': quality}), check=check, timeout=timeout)

    def wander_check(self, *, source: str, format: bool | None = None, disassemble: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Compile Wander source without attaching it, exactly as the engine would run it (components, builtins, `use`d modules from the project). Returns diagnostics (line, column, stable code, message, did-you-mean hint, file for module errors), warnings, and a summary of the behaviors (vars, params, handlers, states, tests). format=true also returns the canonical formatting; disassemble=true the bytecode listing."""
        return self._c.call('wander_check', _args(WanderCheckArgs, {'source': source, 'format': format, 'disassemble': disassemble}), check=check, timeout=timeout)

    def wander_compile_native(self, *, entity: int | str | None = None, force: bool | None = None, auto: bool | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """AOT-compile Wander behaviors to C++ and load them as native code (system clang++, cached by program hash, so unchanged behaviors load instantly). Native code has identical semantics (same results, errors and step budget) and runs hot loops several times faster; anything that fails to build keeps running in the VM. Pass entity to compile its behaviors, or nothing for every behavior in the scene. auto=true compiles every behavior automatically whenever play starts. Edited behaviors fall back to the VM until compiled again."""
        return self._c.call('wander_compile_native', _args(WanderCompileNativeArgs, {'entity': entity, 'force': force, 'auto': auto}), check=check, timeout=timeout)

    def wander_inspect(self, *, entity: int | str, check: bool = False, timeout: float | None = None) -> ToolResult:
        """While playing: the runtime state of an entity's behaviors — current state of each state machine and how long it has been active, handlers waiting in `wait` (and for how long), plus the entity's vars. Use it to debug why a behavior is not doing what its intent says."""
        return self._c.call('wander_inspect', _args(WanderInspectArgs, {'entity': entity}), check=check, timeout=timeout)

    def wander_reference(self, *, topic: str | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """The Wander 2 guide for writing behaviors: syntax, triggers, statements, idioms, and every builtin function with its signature (generated from the builtin registry, including subsystem and native-module builtins). Read it once before writing behaviors. topic="<category or function>" returns detailed entries with parameter types and examples, e.g. topic="physics", topic="list", topic="raycast"."""
        return self._c.call('wander_reference', _args(WanderReferenceArgs, {'topic': topic}), check=check, timeout=timeout)

    def wander_test(self, *, entity: int | str | None = None, name: str | None = None, source: str | None = None, filter: str | None = None, mode: Literal['entity', 'scene', 'isolated'] | None = None, max_seconds: float | None = None, check: bool = False, timeout: float | None = None) -> ToolResult:
        """Run the `test "..."` blocks of a behavior in a sandbox simulation (the real scene is never touched): each test gets a fresh world, ticks once (on start ran), then runs with self = the entity under test; `wait` advances the simulation at 1/60 s, `emit`/`press`/`hold`/`release`/`click` inject input, and `expect` reports failures with the compared values. Pass entity+name (mode "entity" copies that entity's components, tags and vars; "scene" runs inside a copy of the whole scene; "isolated" uses a plain entity) or raw `source`. Returns pass/fail per test, failures with line numbers, logs and simulated time."""
        return self._c.call('wander_test', _args(WanderTestArgs, {'entity': entity, 'name': name, 'source': source, 'filter': filter, 'mode': mode, 'max_seconds': max_seconds}), check=check, timeout=timeout)

    def water_query(self, *, points: list[list[float]], check: bool = False, timeout: float | None = None) -> ToolResult:
        """Height and normal of the animated water surface (FFT ocean) at points — for floating boats, buoys and debris, or placing a pier above the waves. Uses the current effects time."""
        return self._c.call('water_query', _args(WaterQueryArgs, {'points': points}), check=check, timeout=timeout)


